<?php
$branches = $branches ?? [];
$filters = $filters ?? ['q' => '', 'status' => ''];
$statuses = ['active' => ['class' => 'badge-success', 'label' => 'Active'], 'inactive' => ['class' => 'badge-neutral', 'label' => 'Inactive'], 'suspended' => ['class' => 'badge-danger', 'label' => 'Suspended']];
?>
<div class="section-title"><div><span class="eyebrow">Platform administration</span><h2>Locations</h2><p class="text-muted">Monitor every branch and visitor location across the platform.</p></div><a href="<?= site_url('organizations') ?>" class="btn btn-secondary btn-sm">Organizations</a></div>
<div class="card">
  <form class="table-toolbar" method="get" action="<?= site_url('admin/locations') ?>"><div class="table-toolbar__filters"><div class="input-icon-wrap location-search"><span class="input-icon">⌕</span><input type="search" name="q" class="form-control" placeholder="Search location or organization" value="<?= esc($filters['q']) ?>"></div><select name="status" class="form-control" aria-label="Filter by location status"><option value="">All statuses</option><?php foreach ($statuses as $value => $status): ?><option value="<?= esc($value) ?>" <?= $filters['status'] === $value ? 'selected' : '' ?>><?= esc($status['label']) ?></option><?php endforeach; ?></select><button type="submit" class="btn btn-secondary btn-sm">Filter</button><?php if ($filters['q'] || $filters['status']): ?><a href="<?= site_url('admin/locations') ?>" class="btn btn-ghost btn-sm">Clear</a><?php endif; ?></div><span class="text-muted" style="font-size:var(--text-sm);"><?= count($branches) ?> location<?= count($branches) === 1 ? '' : 's' ?></span></form>
  <div class="table-wrap"><table class="data-table"><thead><tr><th>Location</th><th>Organization</th><th>Code</th><th>Staff</th><th>Visits</th><th>Status</th><th>Address</th><th class="cell-actions">Actions</th></tr></thead><tbody>
    <?php if (!$branches): ?><tr><td colspan="8"><div class="empty-state"><div class="empty-state__icon">L</div><h3>No locations found</h3><p>Try changing the search or status filter.</p></div></td></tr><?php else: foreach ($branches as $branch): ?><?php $status = $statuses[$branch['status'] ?? 'active'] ?? $statuses['active']; ?><tr><td><div class="table-person"><div class="avatar location-avatar"><?= esc(strtoupper(substr($branch['name'] ?? '?', 0, 2))) ?></div><div class="table-person__meta"><div class="table-person__name"><?= esc($branch['name'] ?? '') ?></div><div class="table-person__sub"><?= esc($branch['phone'] ?? 'No phone') ?></div></div></div></td><td><?= esc($branch['organization_name'] ?? 'Unassigned') ?></td><td class="cell-muted font-mono"><?= esc($branch['code'] ?? '—') ?></td><td><?= (int) ($branch['staff_count'] ?? 0) ?></td><td><?= (int) ($branch['visit_count'] ?? 0) ?></td><td><span class="badge <?= $status['class'] ?>"><span class="badge__dot"></span><?= esc($status['label']) ?></span></td><td class="cell-muted location-address"><?= esc($branch['address'] ?? '—') ?></td><td class="cell-actions"><a href="<?= site_url('organizations/' . (int) $branch['organization_id'] . '/branches/' . (int) $branch['id']) ?>" class="action-btn"><span>View</span></a></td></tr><?php endforeach; endif; ?>
  </tbody></table></div>
  <?php if ($branches): ?><div class="pagination-bar"><span>Showing <?= count($branches) ?> location<?= count($branches) === 1 ? '' : 's' ?></span><div class="pagination"><?= $pager->links() ?></div></div><?php endif; ?>
